39	}
40	
41	const PROCESSING_FEE = 5;
42	
43	const FIRST_INSURANCE_PERCENT = 10;
44	
45	const BASE_PREMIUMS: Record<string, number> = {
46	  sword: 100,
47	  amulet: 60,
48	  staff: 80,
49	  potion: 40,
50	  rune: 25,
51	  moonstone: 25,
52	};
53	
54	// Percentages MUST go through this helper. Applying them as exact integer
55	// fractions keeps the arithmetic drift-free; the tempting `amount * 1.1`
56	// yields 110.00000000000001 for 100, and since the spec rounds premiums UP
57	// at the very end that drift becomes a whole extra G.
58	const addPercent = (amount: number, percent: number): number =>
59	  (amount * (100 + percent)) / 100;
60	
61	const quote = ({ items }: QuoteStep): StepResult => {
62	  const policyBase = items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
63	  const withFirstInsurance = addPercent(policyBase, FIRST_INSURANCE_PERCENT);
64	
65	  return { premium: Math.ceil(withFirstInsurance + PROCESSING_FEE) };
66	};
67	
68	export const runScenario = (scenario: Scenario): ScenarioResult => ({
69	  // Only quote steps are exercised so far; claim dispatch arrives with its first test.
70	  results: scenario.steps.map((step) => quote(step as QuoteStep)),
71	});
